{
  "name": "@crazy-goat/nexos-provider",
  "version": "1.16.0",
  "description": "Custom AI SDK provider for nexos.ai models (Gemini, Claude, GPT, Codex, Mistral, Codestral, Kimi) in opencode",
  "type": "module",
  "main": "index.mjs",
  "exports": {
    ".": "./index.mjs"
  },
  "scripts": {
    "test": "node --test test-fix-*.mjs"
  },
  "files": [
    "index.mjs",
    "fix-gemini.mjs",
    "fix-claude.mjs",
    "fix-chatgpt.mjs",
    "fix-mistral.mjs",
    "fix-codex.mjs",
    "fix-kimi.mjs",
    "README.md"
  ],
  "keywords": [
    "opencode",
    "ai-sdk",
    "nexos",
    "gemini",
    "provider"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/crazy-goat/nexos-provider.git"
  },
  "homepage": "https://github.com/crazy-goat/nexos-provider",
  "bugs": {
    "url": "https://github.com/crazy-goat/nexos-provider/issues"
  },
  "dependencies": {
    "@ai-sdk/anthropic": "^3.0.78",
    "@ai-sdk/openai-compatible": "2.0.37",
    "ai": "^6.0.85"
  }
}
